#!/usr/bin/env python3
# dbnrecaudit phase_arb.py (reviewer point B7-B9): Arb (256-bit) check of the mpmath-derived scan domain and phase integers.
# (1) every logged shell of rows 1-8 (86 prep.json files): |xs_logged - (X e^u0 + pi t-/4)| and the overshoot xs + K D - (X e^u1 + pi t+/4) >= D.
# (2) given .dat files (regenerated by prep_end.py, prep.json line identical to the logged one): every group's p0, dK, d1, d2, d3 against
#     Arb enclosures of frac(xs_true log b/4pi) 2^64, frac(h log b/4pi) 2^64 (h = D, D/32, D/256, D/2048; D the double); rigorous phase error bound
#     eta = |p0 err| + (K-1)|dK err| + 31|d1 err| + 7|d2 err| + 7|d3 err| units at every cell start of the shell.
# usage: phase_arb.py [DAT:PREPJSON ...]   (cwd = repo root; prints JSON)
import sys, json, math
from fractions import Fraction as Fr
from flint import arb, fmpq, ctx
ctx.prec = 256
X = arb(6000000185827); PI = arb.pi(); T64 = arb(2)**64
Dd = 4*math.pi/math.log(2); Dq = Fr(*Dd.as_integer_ratio()); Da = arb(fmpq(Dq.numerator, Dq.denominator))
def A(fr): fr = Fr(fr); return arb(fmpq(fr.numerator, fr.denominator))
shells = json.load(open('Riemann/Deep/DBNRecAudit/logs/check_logs_shells.json'))
dom = []
for sh in shells:
    pj = json.loads(open('Riemann/Deep/%s/logs/%s.prep.json' % (sh['d'], sh['tag'])).readline())
    tm, tp = A(pj['t'][0]), A(pj['t'][1]); u0, u1 = A(pj['u0']), A(pj['u1'])
    xs_t = X*u0.exp() + PI*tm/4; xe_t = X*u1.exp() + PI*tp/4; xs_l = arb(pj['xs'])
    over = (xs_l + Da*pj['K'] - xe_t)/Da
    dom.append(dict(tag=sh['d'] + '/' + sh['tag'], xs_diff=float(abs(xs_l - xs_t).upper()), overshoot_in_D=float(over.lower())))
res = dict(shells=len(dom), max_xs_diff=max(d['xs_diff'] for d in dom), min_overshoot_in_D=min(d['overshoot_in_D'] for d in dom), dat=[])
def err_units(intval, ball):   # |intval - ball| reduced mod 2^64 in exact/Arb arithmetic, as a float upper bound (units of 2^-64 turn)
    d = arb(intval) - ball
    if d > T64/2: d = d - T64
    elif d < -T64/2: d = d + T64
    assert abs(d) < T64/4
    return float(abs(d).upper())
for spec in sys.argv[1:]:
    datf, pjf = spec.split(':'); pj = json.loads(open(pjf).readline())
    tm = A(pj['t'][0]); u0 = A(pj['u0']); xs_t = X*u0.exp() + PI*tm/4
    f = open(datf); hdr = f.readline().split(); NG, K = int(hdr[0]), int(hdr[1]); assert float(hdr[2]) == Dd and K == pj['K']
    M1, M2, M3 = int(hdr[3]), int(hdr[4]), int(hdr[5]); hs = [Da, Da/M1, Da/(M1*M2), Da/(M1*M2*M3)]
    worst = dict(p0=0.0, dK=0.0, d1=0.0, d2=0.0, d3=0.0, eta=0.0)
    for _ in range(NG):
        w = f.readline().split(); b, nh = int(w[0]), int(w[1]); ints = list(map(int, w[2:7]))
        wt = arb(b).log()/(4*PI)
        v = xs_t*wt; fr = v - v.floor(); e0 = err_units(ints[0], fr*T64)
        es = []
        for h, iv in zip(hs, ints[1:]):
            v = h*wt; fr = v - v.floor(); es.append(err_units(iv, fr*T64))
        eta = e0 + (K - 1)*es[0] + (M1 - 1)*es[1] + (M2 - 1)*es[2] + (M3 - 1)*es[3]
        for k_, val in zip(('p0', 'dK', 'd1', 'd2', 'd3', 'eta'), [e0] + es + [eta]): worst[k_] = max(worst[k_], val)
        for _ in range(nh): f.readline()
    worst['eta_log2_units'] = math.log2(worst['eta']); worst['eta_over_EPSU'] = worst['eta']/2.0**40; worst['eta_over_2^34'] = worst['eta']/2.0**34
    res['dat'].append(dict(dat=datf, K=K, NG=NG, **worst))
print(json.dumps(res))
